// =====================================================================
// Sumário Dinâmico - Entry Point do Taskpane
// Inicialização principal e wiring de eventos
// =====================================================================
import "./taskpane.css";
import { SumarioController } from "./sumarioController";
import { UIManager } from "./uiManager";
// Variáveis globais para acesso pelos botões da fita (commands.ts)
let g_controller = null;
let g_ui = null;
Office.onReady((info) => {
    if (info.host === Office.HostType.PowerPoint) {
        initializeAddin();
    }
    else {
        console.warn("Sumário Dinâmico funciona apenas no PowerPoint");
        document.body.innerHTML = `
      <div style="padding: 20px; text-align: center; color: var(--color-text-secondary);">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="width: 64px; height: 64px; margin-bottom: 16px; opacity: 0.5;">
          <rect x="2" y="3" width="20" height="14" rx="2" ry="2"/>
          <path d="M8 21h8M12 17v4"/>
        </svg>
        <h2>Sumário Dinâmico</h2>
        <p>Este add-in funciona apenas no Microsoft PowerPoint.</p>
        <p style="font-size: 12px; margin-top: 8px;">Host detectado: ${info.host}</p>
      </div>
    `;
    }
});
async function initializeAddin() {
    try {
        g_ui = new UIManager();
        g_controller = new SumarioController(g_ui);
        window.g_controller = g_controller;
        window.g_ui = g_ui;
        await g_controller.initialize();
        g_ui.onAction(async (action) => {
            if (!g_controller)
                return;
            switch (action) {
                case "topo":
                    await g_controller.gerarSumario("topo");
                    break;
                case "rodape":
                    await g_controller.gerarSumario("rodape");
                    break;
                case "atualizar":
                    await g_controller.atualizarSumario();
                    break;
                case "remover":
                    await g_controller.removerSumarioTodos();
                    break;
            }
        });
        bindQuickActionButtons();
        // Sem polling: ler as seções exporta o arquivo inteiro (getFileAsync)
        document.addEventListener("visibilitychange", () => {
            if (document.visibilityState === "visible" && g_controller) {
                g_controller.refreshSectionsList().catch(console.warn);
            }
        });
        console.log("Sumário Dinâmico inicializado com sucesso");
    }
    catch (error) {
        console.error("Erro ao inicializar Sumário Dinâmico:", error);
        g_ui?.showToast("Erro ao inicializar: " + error, "error");
    }
}
function bindQuickActionButtons() {
    const btnTopo = document.getElementById("btnTopo");
    const btnRodape = document.getElementById("btnRodape");
    const btnAtualizar = document.getElementById("btnAtualizar");
    const btnRemover = document.getElementById("btnRemover");
    btnTopo?.addEventListener("click", async () => {
        if (g_controller)
            await g_controller.gerarSumario("topo");
    });
    btnRodape?.addEventListener("click", async () => {
        if (g_controller)
            await g_controller.gerarSumario("rodape");
    });
    btnAtualizar?.addEventListener("click", async () => {
        if (g_controller)
            await g_controller.atualizarSumario();
    });
    btnRemover?.addEventListener("click", async () => {
        if (g_controller)
            await g_controller.removerSumarioTodos();
    });
}
// =====================================================================
// FUNÇÕES GLOBAIS PARA COMMANDS.TS (fita/ribbon)
// =====================================================================
async function gerarSumarioTopo(event) {
    try {
        if (!g_controller) {
            g_controller = new SumarioController();
            await g_controller.initialize();
        }
        await g_controller.gerarSumario("topo");
        event.completed();
    }
    catch (error) {
        console.error("Erro ao gerar sumário no topo:", error);
        event.completed();
    }
}
async function gerarSumarioRodape(event) {
    try {
        if (!g_controller) {
            g_controller = new SumarioController();
            await g_controller.initialize();
        }
        await g_controller.gerarSumario("rodape");
        event.completed();
    }
    catch (error) {
        console.error("Erro ao gerar sumário no rodapé:", error);
        event.completed();
    }
}
async function atualizarSumario(event) {
    try {
        if (!g_controller) {
            g_controller = new SumarioController();
            await g_controller.initialize();
        }
        await g_controller.atualizarSumario();
        event.completed();
    }
    catch (error) {
        console.error("Erro ao atualizar sumário:", error);
        event.completed();
    }
}
async function removerSumario(event) {
    try {
        if (!g_controller) {
            g_controller = new SumarioController();
            await g_controller.initialize();
        }
        await g_controller.removerSumarioTodos();
        event.completed();
    }
    catch (error) {
        console.error("Erro ao remover sumário:", error);
        event.completed();
    }
}
window.gerarSumarioTopo = gerarSumarioTopo;
window.gerarSumarioRodape = gerarSumarioRodape;
window.atualizarSumario = atualizarSumario;
window.removerSumario = removerSumario;
