// =====================================================================
// Sumário Dinâmico - Gerenciador de UI
// Binding de controles, toasts, modais, lista de seções
// =====================================================================
export class UIManager {
    constructor() {
        this.changeCallback = null;
        this.toastContainer = document.getElementById("toastContainer");
        this.helpModal = document.getElementById("helpModal");
        this.sectionsList = document.getElementById("secoesList");
        this.setupEventListeners();
    }
    bindControls(config, onChange) {
        this.changeCallback = onChange;
        this.bindSelect("posicaoPadrao", config.posicaoPadrao);
        this.bindSelect("topoFaixa", config.topoFaixa);
        this.bindRange("topoFaixaAltCm", config.topoFaixaAltCm, (v) => v.toFixed(2) + " cm");
        this.bindNumber("margemEsq", config.margemEsq);
        this.bindNumber("reservaDir", config.reservaDir);
        this.bindInput("fonte", config.fonte);
        this.bindNumber("tamFonte", config.tamFonte);
        this.bindInput("separador", config.separador);
        this.bindColor("rAtual", config.rAtual, "rAtualHex");
        this.bindColor("rPassada", config.rPassada, "rPassadaHex");
        this.bindColor("rFutura", config.rFutura, "rFuturaHex");
        this.bindColor("cFundo", config.cFundo, "cFundoHex");
        this.bindColor("cAtual", config.cAtual, "cAtualHex");
        this.bindColor("cPassada", config.cPassada, "cPassadaHex");
        this.bindColor("cFutura", config.cFutura, "cFuturaHex");
        this.bindColor("eFundo", config.eFundo, "eFundoHex");
        this.bindColor("tAtual", config.tAtual, "tAtualHex");
        this.bindColor("tPassada", config.tPassada, "tPassadaHex");
        this.bindColor("tFutura", config.tFutura, "tFuturaHex");
        this.bindColor("corDestaque", config.corDestaque, "corDestaqueHex");
        this.bindRange("espLinha", config.espLinha, (v) => v + " pt");
        this.bindCheckbox("mostrarLinha", config.mostrarLinha);
        this.bindCheckbox("animarProgresso", config.animarProgresso);
        this.bindCheckbox("travarElementos", config.travarElementos);
        this.bindCheckbox("modoCompactoAuto", config.modoCompactoAuto);
        this.bindRange("durAnimacao", config.durAnimacao, (v) => v + " s");
        this.bindInput("prefixoIgnorar", config.prefixoIgnorar);
        this.bindInput("layoutSemSumario", config.layoutSemSumario);
        this.bindColorTabs();
        this.bindPresets();
        this.bindHelpModal();
    }
    bindSelect(id, value) {
        const el = document.getElementById(id);
        if (!el)
            return;
        el.value = value;
        el.addEventListener("change", () => this.emitChange({ [id]: el.value }));
    }
    bindInput(id, value) {
        const el = document.getElementById(id);
        if (!el)
            return;
        el.value = value;
        el.addEventListener("input", () => this.emitChange({ [id]: el.value }));
        el.addEventListener("change", () => this.emitChange({ [id]: el.value }));
    }
    bindNumber(id, value) {
        const el = document.getElementById(id);
        if (!el)
            return;
        el.value = String(value);
        el.addEventListener("input", () => {
            const num = parseFloat(el.value);
            if (!isNaN(num))
                this.emitChange({ [id]: num });
        });
        el.addEventListener("change", () => {
            const num = parseFloat(el.value);
            if (!isNaN(num))
                this.emitChange({ [id]: num });
        });
    }
    bindRange(id, value, format) {
        const el = document.getElementById(id);
        const valEl = document.getElementById(id + "Value");
        if (!el || !valEl)
            return;
        el.value = String(value);
        valEl.textContent = format(value);
        el.addEventListener("input", () => {
            const num = parseFloat(el.value);
            if (!isNaN(num)) {
                valEl.textContent = format(num);
                this.emitChange({ [id]: num });
            }
        });
        el.addEventListener("change", () => {
            const num = parseFloat(el.value);
            if (!isNaN(num))
                this.emitChange({ [id]: num });
        });
    }
    bindCheckbox(id, value) {
        const el = document.getElementById(id);
        if (!el)
            return;
        el.checked = value;
        el.addEventListener("change", () => this.emitChange({ [id]: el.checked }));
    }
    bindColor(id, value, hexId) {
        const el = document.getElementById(id);
        const hexEl = document.getElementById(hexId);
        if (!el || !hexEl)
            return;
        el.value = value;
        hexEl.textContent = value.toUpperCase();
        el.addEventListener("input", () => {
            hexEl.textContent = el.value.toUpperCase();
            this.emitChange({ [id]: el.value });
        });
        el.addEventListener("change", () => {
            this.emitChange({ [id]: el.value });
        });
    }
    bindColorTabs() {
        const tabs = document.querySelectorAll(".color-tab");
        const panels = document.querySelectorAll(".color-panel");
        tabs.forEach((tab) => {
            tab.addEventListener("click", () => {
                tabs.forEach((t) => t.classList.remove("active"));
                panels.forEach((p) => p.classList.remove("active"));
                tab.classList.add("active");
                const panelId = "colors-" + tab.getAttribute("data-tab");
                const panel = document.getElementById(panelId);
                if (panel)
                    panel.classList.add("active");
            });
        });
    }
    bindPresets() {
        const btnSalvar = document.getElementById("btnSalvarPreset");
        const btnCarregar = document.getElementById("btnCarregarPreset");
        const btnExportar = document.getElementById("btnExportarConfig");
        const fileInput = document.getElementById("fileImportar");
        btnSalvar?.addEventListener("click", () => this.handleSalvarPreset());
        btnCarregar?.addEventListener("click", () => fileInput?.click());
        btnExportar?.addEventListener("click", () => this.handleExportarConfig());
        fileInput?.addEventListener("change", (e) => this.handleImportarConfig(e));
    }
    bindHelpModal() {
        const btnHelp = document.getElementById("btnHelp");
        const closeHelp = document.getElementById("closeHelp");
        btnHelp?.addEventListener("click", () => this.openHelpModal());
        closeHelp?.addEventListener("click", () => this.closeHelpModal());
        this.helpModal.addEventListener("click", (e) => {
            if (e.target === this.helpModal)
                this.closeHelpModal();
        });
    }
    setupEventListeners() {
        document.addEventListener("keydown", (e) => {
            if (e.ctrlKey && e.shiftKey) {
                switch (e.key.toLowerCase()) {
                    case "t":
                        e.preventDefault();
                        this.emitAction("topo");
                        break;
                    case "r":
                        e.preventDefault();
                        this.emitAction("rodape");
                        break;
                    case "u":
                        e.preventDefault();
                        this.emitAction("atualizar");
                        break;
                    case "d":
                        e.preventDefault();
                        this.emitAction("remover");
                        break;
                }
            }
            if (e.key === "Escape") {
                this.closeHelpModal();
            }
        });
    }
    emitChange(updated) {
        if (this.changeCallback) {
            this.changeCallback(updated);
        }
    }
    emitAction(action) {
        const event = new CustomEvent("sumarioAction", { detail: { action } });
        document.dispatchEvent(event);
    }
    onAction(handler) {
        document.addEventListener("sumarioAction", ((e) => {
            handler(e.detail.action);
        }));
    }
    handleSalvarPreset() {
        const name = prompt("Nome do preset:");
        if (!name)
            return;
        const presets = this.getPresets();
        presets[name] = {
            config: this.getCurrentConfigFromUI(),
            timestamp: Date.now(),
        };
        this.savePresets(presets);
        this.renderPresetList(presets);
        this.showToast(`Preset "${name}" salvo`, "success");
    }
    handleExportarConfig() {
        const config = this.getCurrentConfigFromUI();
        const blob = new Blob([JSON.stringify(config, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `sumario-dinamico-config-${new Date().toISOString().slice(0, 10)}.json`;
        a.click();
        URL.revokeObjectURL(url);
        this.showToast("Configuração exportada", "success");
    }
    handleImportarConfig(event) {
        const file = event.target.files?.[0];
        if (!file)
            return;
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const config = JSON.parse(e.target?.result);
                this.updateControls(config);
                if (this.changeCallback)
                    this.changeCallback(config);
                this.showToast("Configuração importada", "success");
            }
            catch {
                this.showToast("Arquivo JSON inválido", "error");
            }
            event.target.value = "";
        };
        reader.readAsText(file);
    }
    getPresets() {
        try {
            const stored = localStorage.getItem("sumarioDinamicoPresets");
            return stored ? JSON.parse(stored) : {};
        }
        catch {
            return {};
        }
    }
    savePresets(presets) {
        localStorage.setItem("sumarioDinamicoPresets", JSON.stringify(presets));
    }
    renderPresetList(presets) {
        const container = document.getElementById("presetList");
        if (!container)
            return;
        const data = presets || this.getPresets();
        container.innerHTML = "";
        if (Object.keys(data).length === 0) {
            container.innerHTML = `<p class="empty-state">Nenhum preset salvo</p>`;
            return;
        }
        for (const [name, { config, timestamp }] of Object.entries(data)) {
            const item = document.createElement("div");
            item.className = "preset-item";
            item.innerHTML = `
        <div class="preset-info">
          <span class="preset-name">${this.escapeHtml(name)}</span>
          <span class="preset-meta">${new Date(timestamp).toLocaleString()}</span>
        </div>
        <div class="preset-actions-inline">
          <button class="icon-btn preset-load" title="Carregar" data-name="${this.escapeHtml(name)}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
              <polyline points="17 8 12 3 7 8"/>
              <line x1="12" y1="3" x2="12" y2="15"/>
            </svg>
          </button>
          <button class="icon-btn preset-delete" title="Excluir" data-name="${this.escapeHtml(name)}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M3 6h18"/>
              <path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/>
              <path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/>
            </svg>
          </button>
        </div>
      `;
            container.appendChild(item);
        }
        container.querySelectorAll(".preset-load").forEach((btn) => {
            btn.addEventListener("click", () => {
                const name = btn.getAttribute("data-name");
                const presets = this.getPresets();
                if (presets[name]) {
                    this.updateControls(presets[name].config);
                    if (this.changeCallback)
                        this.changeCallback(presets[name].config);
                    this.showToast(`Preset "${name}" carregado`, "success");
                }
            });
        });
        container.querySelectorAll(".preset-delete").forEach((btn) => {
            btn.addEventListener("click", () => {
                const name = btn.getAttribute("data-name");
                if (confirm(`Excluir preset "${name}"?`)) {
                    const presets = this.getPresets();
                    delete presets[name];
                    this.savePresets(presets);
                    this.renderPresetList(presets);
                    this.showToast(`Preset "${name}" excluído`, "success");
                }
            });
        });
    }
    updateControls(config) {
        for (const [key, value] of Object.entries(config)) {
            const el = document.getElementById(key);
            if (!el)
                continue;
            if (el instanceof HTMLSelectElement) {
                el.value = String(value);
            }
            else if (el instanceof HTMLInputElement) {
                if (el.type === "checkbox") {
                    el.checked = Boolean(value);
                }
                else if (el.type === "color") {
                    el.value = String(value);
                    const hexEl = document.getElementById(key + "Hex");
                    if (hexEl)
                        hexEl.textContent = String(value).toUpperCase();
                }
                else if (el.type === "range") {
                    el.value = String(value);
                    const valEl = document.getElementById(key + "Value");
                    if (valEl) {
                        const format = this.getRangeFormat(key);
                        valEl.textContent = format(Number(value));
                    }
                }
                else {
                    el.value = String(value);
                }
            }
        }
        this.renderPresetList();
    }
    getRangeFormat(key) {
        const formats = {
            topoFaixaAltCm: (v) => v.toFixed(2) + " cm",
            espLinha: (v) => v + " pt",
            durAnimacao: (v) => v + " s",
        };
        return formats[key] || ((v) => String(v));
    }
    getCurrentConfigFromUI() {
        const config = {};
        const inputs = document.querySelectorAll("input, select");
        inputs.forEach((el) => {
            if (el instanceof HTMLSelectElement) {
                config[el.id] = el.value;
            }
            else if (el instanceof HTMLInputElement) {
                if (el.type === "checkbox") {
                    config[el.id] = el.checked;
                }
                else if (el.type === "color") {
                    config[el.id] = el.value;
                }
                else if (el.type === "range" || el.type === "number") {
                    config[el.id] = parseFloat(el.value);
                }
                else {
                    config[el.id] = el.value;
                }
            }
        });
        return config;
    }
    renderSectionsList(secoes) {
        if (secoes.length === 0) {
            this.sectionsList.innerHTML = `<p class="empty-state">Nenhuma seção encontrada. Crie seções na apresentação (botão direito entre slides → Adicionar Seção).</p>`;
            return;
        }
        this.sectionsList.innerHTML = secoes
            .map((sec) => `
      <div class="secao-item ${sec.ignored ? "ignored" : ""}">
        <span class="secao-index">${sec.index}</span>
        <span class="secao-nome" title="${this.escapeHtml(sec.name)}">${this.escapeHtml(sec.name)}</span>
        <span class="secao-badge">${sec.count} slide${sec.count !== 1 ? "s" : ""}${sec.ignored ? " (ignorada)" : ""}${sec.hasDivider ? " • divisor" : ""}</span>
      </div>
    `)
            .join("");
    }
    updateSectionCount(count) {
        const el = document.getElementById("sectionCount");
        if (el)
            el.textContent = `${count} seção${count !== 1 ? "s" : ""}`;
    }
    showToast(message, type = "info") {
        const toast = document.createElement("div");
        toast.className = `toast ${type}`;
        toast.setAttribute("role", "alert");
        toast.setAttribute("aria-live", "polite");
        const icons = {
            success: '<svg class="toast-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>',
            error: '<svg class="toast-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>',
            info: '<svg class="toast-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>',
            warning: '<svg class="toast-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>',
        };
        toast.innerHTML = `
      ${icons[type]}
      <span class="toast-message">${this.escapeHtml(message)}</span>
      <button class="toast-close" aria-label="Fechar">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    `;
        toast.querySelector(".toast-close")?.addEventListener("click", () => toast.remove());
        this.toastContainer.appendChild(toast);
        setTimeout(() => {
            toast.style.animation = "slideInRight 0.3s ease reverse";
            setTimeout(() => toast.remove(), 300);
        }, 5000);
    }
    setStatus(state, text) {
        const dot = document.getElementById("statusDot");
        const txt = document.getElementById("statusText");
        if (dot) {
            dot.className = "status-dot " + (state === "working" ? "working" : state === "connected" ? "connected" : "");
        }
        if (txt)
            txt.textContent = text;
    }
    openHelpModal() {
        this.helpModal.classList.add("open");
        document.body.style.overflow = "hidden";
        const closeBtn = document.getElementById("closeHelp");
        closeBtn?.focus();
    }
    closeHelpModal() {
        this.helpModal.classList.remove("open");
        document.body.style.overflow = "";
    }
    escapeHtml(text) {
        const div = document.createElement("div");
        div.textContent = text;
        return div.innerHTML;
    }
}
