// =====================================================================
// Sumário Dinâmico - Leitura das seções da apresentação
// A API JavaScript do PowerPoint não expõe seções, então lemos a lista
// direto do arquivo (ppt/presentation.xml → p14:sectionLst)
// =====================================================================
import { unzipSync } from "fflate";
const NS_P = "http://schemas.openxmlformats.org/presentationml/2006/main";
const NS_P14 = "http://schemas.microsoft.com/office/powerpoint/2010/main";
const PRESENTATION_XML = "ppt/presentation.xml";
const TAM_FATIA = 4 * 1024 * 1024;
// getFileAsync só permite um arquivo aberto por vez: serializa as leituras
let filaLeitura = Promise.resolve();
export function lerSecoes() {
    const leitura = filaLeitura.then(async () => {
        const bytes = await obterArquivo();
        const arquivos = unzipSync(bytes, { filter: (f) => f.name === PRESENTATION_XML });
        const conteudo = arquivos[PRESENTATION_XML];
        if (!conteudo)
            throw new Error("Arquivo da apresentação sem presentation.xml");
        return interpretarPresentationXml(new TextDecoder().decode(conteudo));
    });
    filaLeitura = leitura.catch(() => undefined);
    return leitura;
}
function interpretarPresentationXml(xml) {
    const doc = new DOMParser().parseFromString(xml, "application/xml");
    // Ordem dos slides na apresentação (p:sldIdLst/p:sldId/@id)
    const ordem = Array.from(doc.getElementsByTagNameNS(NS_P, "sldId")).map((e) => e.getAttribute("id") ?? "");
    const posicaoPorId = new Map(ordem.map((id, i) => [id, i]));
    const secaoDoSlide = new Array(ordem.length).fill(-1);
    const secoes = Array.from(doc.getElementsByTagNameNS(NS_P14, "section")).map((sec, idxSecao) => {
        const ids = Array.from(sec.getElementsByTagNameNS(NS_P14, "sldId")).map((e) => e.getAttribute("id") ?? "");
        for (const id of ids) {
            const pos = posicaoPorId.get(id);
            if (pos !== undefined)
                secaoDoSlide[pos] = idxSecao;
        }
        return { name: sec.getAttribute("name") ?? "", slideCount: ids.length };
    });
    return { secoes, secaoDoSlide };
}
function obterArquivo() {
    return new Promise((resolve, reject) => {
        Office.context.document.getFileAsync(Office.FileType.Compressed, { sliceSize: TAM_FATIA }, (res) => {
            if (res.status !== Office.AsyncResultStatus.Succeeded) {
                reject(new Error(res.error.message));
                return;
            }
            const file = res.value;
            const partes = [];
            const lerFatia = (i) => {
                file.getSliceAsync(i, (r) => {
                    if (r.status !== Office.AsyncResultStatus.Succeeded) {
                        file.closeAsync();
                        reject(new Error(r.error.message));
                        return;
                    }
                    partes.push(new Uint8Array(r.value.data));
                    if (i + 1 < file.sliceCount) {
                        lerFatia(i + 1);
                    }
                    else {
                        file.closeAsync();
                        resolve(concatenar(partes));
                    }
                });
            };
            lerFatia(0);
        });
    });
}
function concatenar(partes) {
    const total = partes.reduce((s, p) => s + p.length, 0);
    const saida = new Uint8Array(total);
    let offset = 0;
    for (const p of partes) {
        saida.set(p, offset);
        offset += p.length;
    }
    return saida;
}
